u32 rootTypeHashForGroup(i32 group) {
    auto it = std::lower_bound(kGroupRoots.begin(), kGroupRoots.end(), group,
                               [](const GroupRoot& a, i32 g) { return a.group < g; });
    if (it == kGroupRoots.end() || it->group != group)
        return 0;
    return it->typeHash;
}

u32 formatHashForGroup(i32 group) {
    auto it = std::lower_bound(kGroupRoots.begin(), kGroupRoots.end(), group,
                               [](const GroupRoot& a, i32 g) { return a.group < g; });
    if (it == kGroupRoots.end() || it->group != group)
        return 0;
    return it->formatHash;
}

u32 fieldNameHash(const char* name) {
    u32 h = 0;
    if (name) {
        for (const char* p = name; *p; ++p)
            h = static_cast<u32>(static_cast<unsigned char>(*p)) + 33u * h;
    }
    return h & 0x0FFFFFFFu;
}

u32 rootTypeHashForFormatHash(u32 formatHash) {
    auto it = std::lower_bound(kFormatAliases.begin(), kFormatAliases.end(), formatHash,
                               [](const std::pair<u32, u32>& a, u32 h) { return a.first < h; });
    if (it == kFormatAliases.end() || it->first != formatHash)
        return 0;
    return it->second;
}

